#include <vector>
using namespace std;

class Solution {
public:
    long long computeDecimalRepresentation(vector<int>& digits) {
        long long val = 0;
        for (int d : digits) {
            val = val * 10 + d;
        }
        return val;
    }
};

class Solution {
    public long computeDecimalRepresentation(int[] digits) {
        long val = 0;
        for (int d : digits) {
            val = val * 10 + d;
        }
        return val;
    }
}

var computeDecimalRepresentation = function(digits) {
    let val = 0n;
    for (const d of digits) {
        val = val * 10n + BigInt(d);
    }
    return Number(val);
};
